require 'comun.php'; $id=(int)($_GET['id']??0); $s=solicitud($id); $filas=consulta('SELECT h.*,u.nombre FROM historial h JOIN usuarios u ON u.id=h.usuario_id WHERE h.solicitud_id=? ORDER BY h.fecha DESC,h.id DESC',[$id])->fetchAll(PDO::FETCH_ASSOC); inicio('Historial de solicitud #'.$id); ?><section class="section"><h2><?=h($s['servicio'])?></h2><p><?=h($s['descripcion'])?></p><p>Estado actual: <?=h($s['estado'])?></p><div class="tabla-scroll"><table><thead><tr><th>Fecha</th><th>Usuario</th><th>Estado anterior</th><th>Estado nuevo</th></tr></thead><tbody><?php foreach($filas as $f): ?><tr><td><?=h($f['fecha'])?></td><td><?=h($f['nombre'])?></td><td><?=h($f['estado_anterior'])?></td><td><?=h($f['estado_nuevo'])?></td></tr><?php endforeach; ?><?php if(!$filas): ?><tr><td colspan="4">No hay cambios registrados.</td></tr><?php endif; ?></tbody></table></div><br><a class="btn" href="listar.php">Volver</a></section><?php fin(); ?>
